INSERT INTO parks (name, lat, lon, region) SELECT 'Mile High Flea Market', NULL, NULL, 'Colorado, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Mile High Flea Market');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Dragon Coaster', 'Mile High Flea Market', 'Steel', 'Wisdom Rides', 'Wisdom Dragon Wagon', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Dragon Coaster' AND park = 'Mile High Flea Market');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Dragon Coaster' AND c.park = 'Mile High Flea Market' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
